import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";
import StaffNavbar from "../components/StaffNavbar";

export default function Orders() {

  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const API_URL = "http://localhost/Capstone--Development/staff/api_orders.php";

  const fetchOrders = async () => {
    try {
      setLoading(true);
      setError("");

      const res = await fetch(API_URL);

      if (!res.ok) {
        throw new Error("HTTP Error: " + res.status);
      }

      const data = await res.json();

      if (!Array.isArray(data)) {
        throw new Error("Invalid API response");
      }

      const parsed = data.map(order => ({
        ...order,
        items:
          typeof order.items === "string"
            ? JSON.parse(order.items || "[]")
            : order.items || []
      }));

      setOrders(parsed);

    } catch (err) {
      console.error("Fetch error:", err);
      setError(err.message);
      setOrders([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrders();
  }, []);

  const updateStatus = async (id, status) => {
    try {
      const res = await fetch(
        "http://localhost/Capstone--Development/staff/api_update_order_status.php",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ id, status })
        }
      );

      const data = await res.json();

      if (data.status === "success") {
        fetchOrders();
      } else {
        console.error(data.message);
      }

    } catch (err) {
      console.error("Update error:", err);
    }
  };

  const statusColors = {
    Pending: "bg-yellow-100 text-yellow-700",
    Preparing: "bg-blue-100 text-blue-700",
    "To Receive": "bg-purple-100 text-purple-700",
    Completed: "bg-green-100 text-green-700",
  };

  return (
    <div className="bg-[#fafafa] min-h-screen">

      <StaffNavbar />

      <div className="p-8 xl:p-10 pt-24">

        <h1 className="text-3xl font-bold mb-6">
          Orders Management
        </h1>

        {error && (
          <div className="bg-red-100 text-red-600 p-3 rounded mb-4">
            Error: {error}
          </div>
        )}

        {loading ? (
          <p>Loading orders...</p>
        ) : orders.length === 0 ? (
          <p>No orders found</p>
        ) : (

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

            {orders.map(order => (

              <motion.div
                key={order.id}
                whileHover={{ y: -5 }}
                className="bg-white p-6 rounded-xl shadow"
              >

                <div className="flex justify-between mb-3">
                  <h2>#{order.id}</h2>

                  <span className={`px-2 py-1 rounded ${statusColors[order.status]}`}>
                    {order.status}
                  </span>
                </div>

                <div className="mb-3">
                  {order.items.map((item, i) => (
                    <div key={i} className="flex justify-between text-sm">
                      <span>{item.name} x{item.qty}</span>
                      <span>₱{Number(item.price) * item.qty}</span>
                    </div>
                  ))}
                </div>

                <div className="font-bold mb-3">
                  Total: ₱{Number(order.total).toLocaleString()}
                </div>

                <div className="flex gap-2 flex-wrap">

                  {["Pending", "Preparing", "To Receive", "Completed"].map(status => (
                    <button
                      key={status}
                      onClick={() => updateStatus(order.id, status)}
                      className="px-2 py-1 text-xs bg-gray-200 rounded"
                    >
                      {status}
                    </button>
                  ))}

                </div>

              </motion.div>

            ))}

          </div>

        )}

      </div>
    </div>
  );
}
